import React from 'react';
import Header from './Header'; // Assuming a Header component will be created

// Basic layout component
const Layout = ({ children }) => {
  return (
    <>
      <Header />
      <main style={{ padding: '20px' }}> {/* Basic inline styling for now */}
        {children}
      </main>
      {/* Footer could go here */}
    </>
  );
};

export default Layout;
